// Luminary Co. - Minified JavaScript
if('serviceWorker' in navigator){window.addEventListener('load',()=>{navigator.serviceWorker.register('/js/sw.js').then(registration=>{console.log('SW registered: ',registration)}).catch(registrationError=>{console.log('SW registration failed: ',registrationError)})})}document.addEventListener('DOMContentLoaded',function(){const mobileMenuButton=document.getElementById('mobile-menu-button');const mobileMenu=document.getElementById('mobile-menu');if(mobileMenuButton&&mobileMenu){mobileMenuButton.addEventListener('click',()=>{mobileMenu.classList.toggle('hidden')})}document.querySelectorAll('a[href^="#"]').forEach(anchor=>{anchor.addEventListener('click',function(e){e.preventDefault();const targetId=this.getAttribute('href');const targetElement=document.querySelector(targetId);if(targetElement){targetElement.scrollIntoView({behavior:'smooth'});if(mobileMenu&&!mobileMenu.classList.contains('hidden')){mobileMenu.classList.add('hidden')}}})});initializeTestimonialSlider();initializeFadeInEffects();initializeLazyLoading();initializeVideoFallback();initializeTeamPageEnhancements()});function initializeTeamPageEnhancements(){const teamCards=document.querySelectorAll('.team-card');if(teamCards.length===0)return;teamCards.forEach(card=>{const imageContainer=card.querySelector('.team-image-container');const img=card.querySelector('img');if(imageContainer&&img){imageContainer.classList.add('loading');if(img.complete){imageContainer.classList.remove('loading')}else{img.addEventListener('load',()=>{imageContainer.classList.remove('loading')});img.addEventListener('error',()=>{imageContainer.classList.remove('loading');imageContainer.style.background='linear-gradient(135deg, #1a1a1a 0%, #2a2a2a 100%)';imageContainer.innerHTML='<div class="flex items-center justify-center h-full text-gray-500"><span>Image unavailable</span></div>'})}}card.addEventListener('mousemove',(e)=>{const rect=card.getBoundingClientRect();const x=((e.clientX-rect.left)/rect.width)*100;const y=((e.clientY-rect.top)/rect.height)*100;card.style.setProperty('--mouse-x',`${x}%`);card.style.setProperty('--mouse-y',`${y}%`)});card.addEventListener('mouseleave',()=>{card.style.setProperty('--mouse-x','50%');card.style.setProperty('--mouse-y','50%')})});const teamObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.style.animationPlayState='running'}});},{threshold:0.1,rootMargin:'0px 0px -50px 0px'});teamCards.forEach(card=>{teamObserver.observe(card)});teamCards.forEach(card=>{card.addEventListener('mouseenter',()=>{card.style.zIndex='10'});card.addEventListener('mouseleave',()=>{card.style.zIndex='1'})})}function initializeTestimonialSlider(){const slider=document.querySelector('#testimonial-slider .flex');const dotsContainer=document.getElementById('testimonial-dots');if(!slider||!dotsContainer)return;const testimonials=slider.children;let currentIndex=0;Array.from(testimonials).forEach((_,index)=>{const dot=document.createElement('button');dot.classList.add('w-3','h-3','rounded-full','transition-colors');dot.classList.add(index===0?'bg-golden-yellow':'bg-gray-700');dot.addEventListener('click',()=>{goToSlide(index)});dotsContainer.appendChild(dot)});const dots=dotsContainer.children;function goToSlide(index){slider.style.transform=`translateX(-${index*100}%)`;currentIndex=index;updateDots()}function updateDots(){Array.from(dots).forEach((dot,index)=>{dot.classList.toggle('bg-golden-yellow',index===currentIndex);dot.classList.toggle('bg-gray-700',index!==currentIndex)})}setInterval(()=>{let nextIndex=(currentIndex+1)%testimonials.length;goToSlide(nextIndex)},5000)}function initializeFadeInEffects(){const faders=document.querySelectorAll('.fade-in');if(faders.length===0)return;const appearOnScroll=new IntersectionObserver(function(entries,appearOnScroll){entries.forEach(entry=>{if(!entry.isIntersecting){return}else{entry.target.classList.add('visible');appearOnScroll.unobserve(entry.target)}});},{threshold:0.2});faders.forEach(fader=>{appearOnScroll.observe(fader)})}function initializeLazyLoading(){const images=document.querySelectorAll('img[loading="lazy"]');if(images.length===0)return;const imageObserver=new IntersectionObserver((entries,observer)=>{entries.forEach(entry=>{if(entry.isIntersecting){const img=entry.target;img.src=img.dataset.src||img.src;img.classList.remove('lazy');observer.unobserve(img)}})});images.forEach(img=>{if(img.dataset.src){imageObserver.observe(img)}})}function initializeVideoFallback(){const video=document.querySelector('.hero-video');const fallback=document.querySelector('.video-fallback');if(!video||!fallback)return;video.addEventListener('error',()=>{fallback.classList.add('show');video.style.display='none'});video.addEventListener('loadeddata',()=>{fallback.classList.remove('show')})}